ALTER TABLE merchants ADD COLUMN logo_size integer NOT NULL DEFAULT 43 CHECK(logo_size BETWEEN 32 AND 72);
CREATE OR REPLACE VIEW public_merchant_brands WITH (security_barrier=true) AS SELECT id,slug,name,status,timezone,primary_color,accent_color,surface_color,template,terms,logo_asset_id,stamp_shape,stamp_icon,stamp_style,logo_style,logo_size FROM merchants WHERE status IN ('active','trial');
CREATE OR REPLACE FUNCTION my_cards() RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT jsonb_build_object('id',ms.id,'merchant_id',m.id,'merchant_slug',m.slug,'merchant_name',m.name,'alias',cp.alias,'program_id',p.id,'program_version_id',v.id,'program_version',v.version,'program_name',p.name,'threshold',v.threshold,'balance',a.balance,'cycle_number',a.cycle_number,'cycle_renewed_at',a.cycle_renewed_at,'pending_rewards',(SELECT count(*)::int FROM reward_grants r WHERE r.membership_id=ms.id AND r.status='available' AND r.expires_at>now()),'display_balance',CASE WHEN EXISTS(SELECT 1 FROM reward_grants r WHERE r.membership_id=ms.id AND r.status='available' AND r.expires_at>now()) THEN v.threshold ELSE a.balance END,'revision',a.revision,'primary_color',m.primary_color,'accent_color',m.accent_color,'surface_color',m.surface_color,'template',m.template,'logo_style',m.logo_style,'logo_size',m.logo_size,'stamp_shape',m.stamp_shape,'stamp_icon',m.stamp_icon,'stamp_style',m.stamp_style,'reward_title',v.reward_title,'reward_terms',v.reward_terms,'status',ms.status,'merchant_status',m.status,'earning_active',p.status='active' AND m.status<>'suspended' AND (v.ends_at IS NULL OR v.ends_at>now()),'joined_at',ms.joined_at)
 FROM memberships ms JOIN tenant_customer_profiles cp ON cp.id=ms.profile_id JOIN merchants m ON m.id=ms.merchant_id JOIN programs p ON p.id=ms.program_id JOIN program_versions v ON v.id=ms.program_version_id JOIN loyalty_accounts a ON a.membership_id=ms.id
 WHERE ms.user_id=app_user() ORDER BY ms.joined_at DESC
$$;
